for row in extras:
    (slug, name, esp, zones, needs, summary, que, bens, quien, sesiones, duracion, faqs, related, note) = row
    items.append(T(slug, name, esp, zones, needs, summary, que, bens, quien, sesiones, duracion, faqs, related, True, note, False))

slugs = [i["slug"] for i in items]
assert len(slugs) == len(set(slugs)), "slug repetido"
for i in items:
    missing = [r for r in i["related"] if r not in slugs]
    if missing:
        raise SystemExit(f"{i['slug']} related missing {missing}")
    assert len(i["beneficios"]) >= 3
    assert len(i["faqs"]) >= 2
    assert i["queEs"] and i["sesiones"] and i["zones"] and i["needs"]

out = Path(__file__).resolve().parents[1] / "src" / "data" / "treatments.json"
out.write_text(json.dumps(items, ensure_ascii=False, indent=2), encoding="utf-8")
audit = sum(1 for i in items if i["inAudit44"])
print(f"{len(items)} tratamientos, {audit} del inventario 44 (sin la página x)")
